/**
 * sensor_hal_stm32n6.c
 * --------------------
 * TRON Contest — STM32N6570-DK / µT-Kernel 3.0
 *
 * Hardware Abstraction Layer implementation for:
 *   AD8232  ECG   → ADC1 (PA0, single-ended, 12-bit, DMA)
 *   MAX30102 PPG  → I2C1 (PB8=SCL, PB9=SDA), INT → PB0
 *   MPU6050  IMU  → I2C1 shared bus, INT → PC1
 *   TMP117   Temp → I2C1 shared bus
 *
 * All I2C transfers use HAL blocking calls with a 10 ms timeout.
 * Replace with DMA/IT variants for higher throughput if needed.
 *
 * NOTE: hi2c1 and hadc1 extern handles must be declared in main.c
 *       (generated by STM32CubeMX).
 */

#include "sensor_hal_stm32n6.h"
#include "wearable_sensors.h"

/* STM32N6xx HAL headers (provided by STM32CubeMX) */
#include "stm32n6xx_hal.h"

#include <math.h>
#include <string.h>
#include <stdio.h>

/* ── Extern handles from main.c (CubeMX-generated) ─────────────────────── */
extern I2C_HandleTypeDef  hi2c1;
extern ADC_HandleTypeDef  hadc1;

/* ── Internal helpers ───────────────────────────────────────────────────── */
#define I2C_TIMEOUT_MS  10u

static bool i2c_write_reg(uint8_t dev_addr, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = {reg, val};
    return HAL_I2C_Master_Transmit(&hi2c1,
                                   (uint16_t)(dev_addr << 1),
                                   buf, 2,
                                   I2C_TIMEOUT_MS) == HAL_OK;
}

static bool i2c_read_regs(uint8_t dev_addr, uint8_t reg,
                           uint8_t *dst, uint16_t len)
{
    /* Write register pointer */
    if (HAL_I2C_Master_Transmit(&hi2c1,
                                (uint16_t)(dev_addr << 1),
                                &reg, 1,
                                I2C_TIMEOUT_MS) != HAL_OK) return false;
    /* Read data */
    return HAL_I2C_Master_Receive(&hi2c1,
                                  (uint16_t)(dev_addr << 1),
                                  dst, len,
                                  I2C_TIMEOUT_MS) == HAL_OK;
}

/* ══════════════════════════════════════════════════════════════════════════
 *  HAL_Sensors_Init
 *  Called once from usermain() before any task is started.
 * ══════════════════════════════════════════════════════════════════════════ */
bool HAL_Sensors_Init(void)
{
    bool ok = true;

    /* ── MAX30102: SpO2+HR mode, 100 sps, 18-bit, LED current 7 mA ──── */
    ok &= i2c_write_reg(MAX30102_I2C_ADDR, MAX30102_REG_MODE_CFG,  0x03); /* SpO2 mode  */
    ok &= i2c_write_reg(MAX30102_I2C_ADDR, MAX30102_REG_SPO2_CFG,  0x27); /* 100sps,18b */
    ok &= i2c_write_reg(MAX30102_I2C_ADDR, MAX30102_REG_LED1_PA,   0x24); /* Red ~7 mA  */
    ok &= i2c_write_reg(MAX30102_I2C_ADDR, MAX30102_REG_LED2_PA,   0x24); /* IR  ~7 mA  */

    /* ── MPU6050: wake, 100 Hz output, ±4g accel, ±500°/s gyro ─────── */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_PWR_MGMT_1,  0x01); /* CLK=PLL   */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_SMPLRT_DIV,  0x09); /* 1kHz/10=100Hz */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_CONFIG,       0x03); /* DLPF 44Hz  */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_GYRO_CFG,     0x08); /* ±500°/s    */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_ACCEL_CFG,    0x08); /* ±4g        */
    ok &= i2c_write_reg(MPU6050_I2C_ADDR, MPU6050_REG_INT_ENABLE,   0x01); /* DataReady  */

    /* ── TMP117: continuous conversion, 125 ms averaging ────────────── */
    /* Config: MOD[1:0]=00 (continuous), AVG[1:0]=01 (8 avg), CONV=010  */
    uint8_t tmp_cfg[2] = {0x02, 0x20};
    if (HAL_I2C_Master_Transmit(&hi2c1,
                                (uint16_t)(TMP117_I2C_ADDR << 1),
                                tmp_cfg, 2,
                                I2C_TIMEOUT_MS) != HAL_OK) ok = false;

    /* ── ADC1 for AD8232: already configured by CubeMX, start DMA ─── */
    HAL_ADC_Start(&hadc1);

    return ok;
}

/* ══════════════════════════════════════════════════════════════════════════
 *  AD8232 ECG — ADC1 poll read
 * ══════════════════════════════════════════════════════════════════════════ */
int16_t HAL_ECG_ReadSample(void)
{
    if (HAL_ADC_PollForConversion(&hadc1, 2) != HAL_OK) return 0;
    uint32_t raw = HAL_ADC_GetValue(&hadc1);        /* 12-bit 0..4095      */
    return (int16_t)((int32_t)raw - 2048);          /* centre around zero  */
}

/* ══════════════════════════════════════════════════════════════════════════
 *  MAX30102 — FIFO burst read
 * ══════════════════════════════════════════════════════════════════════════ */
uint8_t HAL_MAX30102_ReadFIFO(uint32_t *red_buf, uint32_t *ir_buf,
                               uint8_t max_samples)
{
    uint8_t wr_ptr = 0, rd_ptr = 0;
    if (!i2c_read_regs(MAX30102_I2C_ADDR, MAX30102_REG_FIFO_WR_PTR, &wr_ptr, 1)) return 0;
    if (!i2c_read_regs(MAX30102_I2C_ADDR, MAX30102_REG_FIFO_RD_PTR, &rd_ptr, 1)) return 0;

    uint8_t n_avail = (uint8_t)((wr_ptr - rd_ptr + 32u) % 32u);
    uint8_t n = (n_avail < max_samples) ? n_avail : max_samples;

    for (uint8_t i = 0; i < n; i++) {
        uint8_t raw[6];
        if (!i2c_read_regs(MAX30102_I2C_ADDR, MAX30102_REG_FIFO_DATA, raw, 6)) break;
        red_buf[i] = ((uint32_t)(raw[0] & 0x03) << 16) |
                     ((uint32_t) raw[1]           << 8)  |
                      (uint32_t) raw[2];
        ir_buf[i]  = ((uint32_t)(raw[3] & 0x03) << 16) |
                     ((uint32_t) raw[4]           << 8)  |
                      (uint32_t) raw[5];
    }
    return n;
}

/**
 * Simple ratio-of-ratios SpO2 estimate (prototype quality).
 * For production, replace with Maxim AN6612 calibration curve.
 */
float HAL_MAX30102_ComputeSpO2(const uint32_t *ir_buf, uint8_t n)
{
    if (n < 2) return 98.0f;

    /* AC/DC estimate via min/max */
    uint32_t ir_max = ir_buf[0], ir_min = ir_buf[0];
    for (uint8_t i = 1; i < n; i++) {
        if (ir_buf[i] > ir_max) ir_max = ir_buf[i];
        if (ir_buf[i] < ir_min) ir_min = ir_buf[i];
    }
    float dc = (float)(ir_max + ir_min) / 2.0f;
    float ac = (float)(ir_max - ir_min);
    if (dc < 1.0f) return 95.0f;

    /* Empirical prototype curve: SpO2 ≈ 110 - 25 × R  (R = AC/DC) */
    float R = ac / dc;
    float spo2 = 110.0f - 25.0f * R;
    if (spo2 > 100.0f) spo2 = 100.0f;
    if (spo2 <  70.0f) spo2 =  70.0f;
    return spo2;
}

/* ══════════════════════════════════════════════════════════════════════════
 *  MPU6050 — register-burst read (14 bytes: accel + temp + gyro)
 * ══════════════════════════════════════════════════════════════════════════ */
bool HAL_MPU6050_ReadRaw(int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t raw[14];
    if (!i2c_read_regs(MPU6050_I2C_ADDR, MPU6050_REG_ACCEL_XOUT_H, raw, 14))
        return false;

    *ax = (int16_t)((raw[0]  << 8) | raw[1]);
    *ay = (int16_t)((raw[2]  << 8) | raw[3]);
    *az = (int16_t)((raw[4]  << 8) | raw[5]);
    /* raw[6..7] = temperature (skip) */
    *gx = (int16_t)((raw[8]  << 8) | raw[9]);
    *gy = (int16_t)((raw[10] << 8) | raw[11]);
    *gz = (int16_t)((raw[12] << 8) | raw[13]);
    return true;
}

/* ══════════════════════════════════════════════════════════════════════════
 *  TMP117 — one-shot temperature read
 * ══════════════════════════════════════════════════════════════════════════ */
float HAL_TMP117_ReadTempC(void)
{
    uint8_t raw[2];
    if (!i2c_read_regs(TMP117_I2C_ADDR, TMP117_REG_TEMP_RESULT, raw, 2))
        return 33.8f;   /* safe default: normal skin temp */

    int16_t counts = (int16_t)((raw[0] << 8) | raw[1]);
    return (float)counts * TMP117_TEMP_RESOLUTION;
}

/* ══════════════════════════════════════════════════════════════════════════
 *  Composite packet fill — used by Task_SensorIngest
 * ══════════════════════════════════════════════════════════════════════════ */
bool HAL_Sensors_ReadPacket(RawSensorPacket_t *pkt)
{
    if (!pkt) return false;
    memset(pkt, 0, sizeof(*pkt));

    /* Timestamp from µT-Kernel system clock */
    extern uint32_t tk_get_utim(void);   /* µT-Kernel time API              */
    pkt->timestamp_ms = tk_get_utim();

    pkt->ecg_raw    = HAL_ECG_ReadSample();

    /* PPG: read up to 4 FIFO samples, compute SpO2 */
    uint32_t red[4], ir[4];
    uint8_t n = HAL_MAX30102_ReadFIFO(red, ir, 4);
    pkt->ppg_red  = (n > 0) ? red[0] : 0;
    pkt->ppg_ir   = (n > 0) ? ir[0]  : 0;
    pkt->spo2_pct = HAL_MAX30102_ComputeSpO2(ir, n);

    pkt->valid = HAL_MPU6050_ReadRaw(
        &pkt->accel_x_raw, &pkt->accel_y_raw, &pkt->accel_z_raw,
        &pkt->gyro_x_raw,  &pkt->gyro_y_raw,  &pkt->gyro_z_raw);

    pkt->skin_temp_c = HAL_TMP117_ReadTempC();
    return pkt->valid;
}
